/**
 * Flat config for the gate toolchain.
 *
 * Layering follows the project gate convention: correctness rules stay at
 * `error` (the pre-commit hook blocks on them), while complexity and size
 * rules stay at `warn` and are counted against gate/lint_baseline.json.
 *
 * The built browser artifact `packages/<name>/client.js` is generated by
 * build.mjs from src/client.js, so it is never linted.
 */

import js from '@eslint/js'
import globals from 'globals'
import prettier from 'eslint-config-prettier'

export default [
  {
    ignores: [
      '**/node_modules/**',
      'packages/*/client.js',
      // Published snapshot the desktop profile links to: a copy of the built
      // artifact, never hand-written.
      '.release/**',
      // Scratch space for one-off probes; not part of the project.
      '.tmp/**',
      'gate/reports/**',
      'coverage/**',
      'docs/**',
    ],
  },

  // Hand-written client source runs in the browser page.
  {
    files: ['packages/*/src/**/*.js'],
    languageOptions: {
      ecmaVersion: 2023,
      sourceType: 'module',
      globals: { ...globals.browser },
    },
  },

  // Host half, build script, gate scripts and release tooling run in Node.
  {
    files: ['packages/*/index.js', 'packages/*/build.mjs', 'gate/**/*.mjs', 'scripts/**/*.mjs'],
    languageOptions: {
      ecmaVersion: 2023,
      sourceType: 'module',
      globals: { ...globals.node },
    },
  },

  js.configs.recommended,

  // `catch {}` is deliberate here: every empty catch is a best-effort cleanup
  // or an optional-service probe whose failure must not break rendering.
  {
    rules: {
      'no-empty': ['error', { allowEmptyCatch: true }],
    },
  },

  // Complexity and size: warnings, frozen in the ratchet baseline.
  {
    files: [
      'packages/*/src/**/*.js',
      'packages/*/index.js',
      'packages/*/build.mjs',
      'gate/**/*.mjs',
      'test/**/*.js',
    ],
    rules: {
      complexity: ['warn', 10],
      'max-depth': ['warn', 4],
      'max-lines-per-function': ['warn', { max: 150, skipBlankLines: true, skipComments: true }],
      'max-params': ['warn', 4],
      'no-unused-vars': ['warn', { argsIgnorePattern: '^_', caughtErrorsIgnorePattern: '^_' }],
    },
  },

  // Test files may use the node:test shape freely.
  {
    files: ['test/**/*.js', 'packages/*/test/**/*.js'],
    languageOptions: {
      ecmaVersion: 2023,
      sourceType: 'module',
      globals: { ...globals.node },
    },
  },

  // Prettier owns formatting: this must stay last.
  prettier,
]
